parameters.jsonBody:
={
  "type": "page",
  "title": {{ JSON.stringify($('When Executed by Another Workflow').first().json.project_name + ' - Personas & Roles') }},
  "space": {
    "key": {{ JSON.stringify($('When Executed by Another Workflow').first().json.confluence_space_key) }}
  },
  "body": {
    "storage": {
      "value": {{ JSON.stringify((() => {
        const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const row = (tag, vals) => '<tr>' + vals.map(v => '<' + tag + '>' + esc(v) + '</' + tag + '>').join('') + '</tr>';
        const table = (headers, rows) => '<table><tbody>' + row('th', headers) + rows.map(r => row('td', r)).join('') + '</tbody></table>';
        const { personas, roles } = $json.output;
        return '<h2>Personas</h2>'
          + table(['Nom', 'Description socio-professionnelle', 'Objectif', 'Priorité', 'Justification'],
              personas.map(p => [p.name, p.socio_professional_description, p.usage_goal, p.priority, p.justification]))
          + '<h2>Rôles</h2>'
          + table(['Nom', 'Description', 'Niveau de permission', 'Justification'],
              roles.map(r => [r.name, r.description, r.permission_level, r.justification]));
      })()) }},
      "representation": "storage"
    }
  }
}
